(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.015+t*0.3)*20 + Math.cos(y*0.012-t*0.2)*15;
  const w1y = Math.cos(y*0.015-t*0.25)*20 + Math.sin(x*0.013+t*0.35)*15;
  const w2x = Math.sin((x+w1x)*0.02+t*0.5)*10 + Math.cos((y+w1y)*0.018-t*0.4)*8;
  const w2y = Math.cos((y+w1y)*0.02-t*0.45)*10 + Math.sin((x+w1x)*0.019+t*0.55)*8;
  const sx = x + w1x + w2x, sy = y + w1y + w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65)*55, 0.11, 2.1],
    [400+Math.cos(t*0.55+2)*60, 200+Math.sin(t*0.75+1)*50, 0.13, 1.4]
