  let aS = 0, iS = 0;
  for (const [sX, sY, f, sp] of src) {
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    aS += Math.sin(d*f - t*sp) + Math.sin(d*f*1.5 - t*sp*0.8 + 0.7)*0.4;
    iS += Math.sin(d*f*0.7 + t*sp*0.6 + 1.5) + Math.cos(d*f*0.5 - t*sp*0.4)*0.3;
  }
  const act = aS/8, inh = iS/8;
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8) + Math.sin(sx*0.03-sy*0.04+t*1.1))/2
    + Math.sin((sx+sy)*0.12+t*2.5)*0.2 + Math.sin((sx-sy)*0.1-t*2)*0.2
    + Math.sin(sx*0.08+t*1.8)*Math.cos(sy*0.06-t*1.3)*0.15;
  const dist = Math.sqrt((sx-cx)**2 + (sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
  const spiral = (Math.sin(dist*0.05-ang*3-t*1.5) + Math.sin(dist*0.04+ang*4-t*1.2))*0.4
    + Math.sin(dist*0.07-ang*2-t*2.5)*0.2;
  const vc = [[Math.sin(t*0.3)*80+240, Math.cos(t*0.25)*60+120],[Math.cos(t*0.4+1)*100+160, Math.sin(t*0.35+2)*70+80],
    [Math.sin(t*0.35+3)*90+320, Math.cos(t*0.45+1)*80+160],[Math.cos(t*0.3+4)*70+400, Math.sin(t*0.4+3)*60+60],
