    if (d < minD) { secD = minD; minD = d; } else if (d < secD) secD = d;
  }
  const voronoi = Math.sin((secD-minD)*0.3 + t*1.5)*0.35;
  const rawR = act - inh*0.7 + bg*0.3 + spiral + voronoi;
  const reaction = Math.tanh(rawR * 2.8);
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15) + Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const grain = Math.sin(sx*0.7+t*3)*Math.sin(sy*0.8-t*2.5)*Math.sin((sx+sy)*0.5+t*1.8)*0.08;
  const blend = reaction*0.55 + cell*0.2 + grain*0.1 + Math.tanh((reaction-cell)*3)*0.15;
  const v = blend*0.5+0.5;
  const pal = [[4,8,38],[10,30,78],[16,62,115],[22,100,130],[38,148,142],[95,178,155],
    [175,198,135],[215,190,110],[230,158,90],[205,110,75],[155,55,62],[75,22,52],[20,10,44],[4,8,38]];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const sharp = Math.abs(reaction) > 0.6 ? 1.0 + Math.abs(reaction)*0.25 : 1.0;
  const lum = 0.72 + Math.sin(reaction*Math.PI)*0.28;
  const m = lum * sharp;
  return [
    Math.min(255, (pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*m)|0,
    Math.min(255, (pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*m)|0,
    Math.min(255, (pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*m)|0
  ];
}
